mapper.sql:
from t_article a inner join t_user u on a.userId = u.id left join t_board b on a.boardId = b.id where a.deleteState = 0 and a.state = 0 and b.deleteState = 0
and a.boardId = #{boardId,jdbcType=BIGINT}
and ( a.title like concat('%', #{keyword,jdbcType=VARCHAR}, '%') or a.content like concat('%', #{keyword,jdbcType=VARCHAR}, '%') )

mapper.select:
select u.id as u_id, u.avatarUrl as u_avatarUrl, u.nickname as u_nickname, u.username as u_username, b.id as b_id, b.name as b_name, b.bizType as b_bizType, a.id, a.boardId, a.userId, a.title, a.visitCount, a.replyCount, a.likeCount, a.topState, a.essenceState, a.state, a.deleteState, a.createTime, a.updateTime, a.bizType, a.extJson from t_article a left join t_user u on a.userId = u.id left join t_board b on a.boardId = b.id
and ( a.title like concat('%', #{keyword,jdbcType=VARCHAR}, '%') or u.nickname like concat('%', #{keyword,jdbcType=VARCHAR}, '%') or u.username like concat('%', #{keyword,jdbcType=VARCHAR}, '%') or b.name like concat('%', #{keyword,jdbcType=VARCHAR}, '%') )
order by a.deleteState asc, a.createTime desc limit #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}
